"""Generate French Codex and illustrated report from current contracts and verified receipts.
No image generation: PNGs are embedded byte-for-byte from Chromium.
"""
from pathlib import Path
import json,re,html,base64,hashlib
R=Path(__file__).resolve().parent.parent
J=lambda p:json.loads((R/p).read_text());e=lambda s:html.escape(str(s))
C=J('report/CONTRATS_LEVEL_DESIGN_V112.json');B=J('report/browser-results-v112.json');D=J('report/beacon-drive-v112.json')
assert all(t['ok'] for t in B['tests']) and not B['pageErrors'] and not B['consoleErrors']
assert B['htmlSha256']==hashlib.sha256((R/'JOUER_ALIENS_V112.html').read_bytes()).hexdigest()
node=int(re.search(r'# pass (\d+)',(R/'report/node-tests-v112.txt').read_text()).group(1))
STYLE='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#0a1219;color:#c9d7dd;font:16px/1.85 system-ui,Arial,sans-serif}main{max-width:1180px;margin:auto;padding:54px 32px 90px}a{color:#c3ddda}h1{font:400 clamp(42px,6vw,76px)/1.08 Georgia,serif;color:#e9e6d9;max-width:960px;margin:24px 0 28px}h2{font:400 30px/1.3 Georgia,serif;color:#d7e4e7;margin:40px 0 16px;border-top:1px solid #354d5d;padding-top:28px}h3{font-size:19px;color:#d5c6a3;font-weight:500}.kicker{font:11px/1.5 monospace;letter-spacing:.23em;color:#85a9bd;text-transform:uppercase}.lead{font-size:21px;max-width:930px;line-height:1.6}.callout{padding:19px 23px;border-left:3px solid #b49b64;background:#182933;color:#c6d9d9;margin:26px 0}.metrics{display:flex;flex-wrap:wrap;gap:14px}.metric{padding:16px 23px;border:1px solid #35505c;background:#12232e;min-width:158px}.metric strong{font:400 33px Georgia,serif;display:block;color:#d6c7a4}.metric small{font-size:12px;color:#92acb8}nav{display:flex;flex-wrap:wrap;gap:21px;margin:24px 0}table{border-collapse:collapse;width:100%;font-size:12px;line-height:1.55;margin:20px 0}th,td{padding:11px;border:1px solid #354b58;text-align:left;vertical-align:top}th{background:#1d3441}tr:nth-child(even){background:#13232d}.rooms{margin-top:28px}.room{border:1px solid #38566a;background:linear-gradient(130deg,#192e3a80,#101e2780);padding:26px;margin:26px 0}.room h2{border:0;padding:0;margin-top:0}.diagram{width:100%;height:auto;background:#101e26;border:1px solid #344e5f}.small{font:12px/1.7 monospace;color:#89a4b2;overflow-wrap:anywhere}figcaption{overflow-wrap:anywhere}figure{margin:30px 0}img{width:100%;height:auto;display:block;border:1px solid #496878}figcaption{font-size:13px;color:#9ab2bd;margin-top:10px}details{border:1px solid #3d5567;background:#11232d;padding:17px;margin:16px 0}summary{cursor:pointer;color:#c8dfe1}input{padding:15px;width:100%;background:#142937;color:#dde9e9;border:1px solid #6e92a1;font:15px system-ui}code,pre{font:12px/1.7 monospace;overflow-wrap:anywhere}pre{background:#0b1c26;padding:18px;white-space:pre-wrap}.hide{display:none}.chip{padding:4px 10px;border:1px solid #4c697b;font-size:11px;color:#b5cfd4}.two{display:grid;grid-template-columns:1fr 1fr;gap:20px}@media(max-width:720px){main{padding:25px 16px}.room{padding:15px}h1{font-size:40px}.lead{font-size:18px}table{display:block;overflow-x:auto}.two{display:block}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}@media print{body{background:white;color:#222}h1,h2,h3{color:#222}nav,input{display:none}figure,.room{break-inside:avoid}main{padding:0}}'''
def page(title,b,js=''):return f'<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)}</title><style>{STYLE}</style></head><body><main>{b}</main>{js}</body></html>'
def table(head,rows):return '<table><thead><tr>'+''.join('<th>'+e(h)+'</th>' for h in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+e(v)+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table>'
def metrics(rows):return '<div class="metrics">'+''.join(f'<div class="metric"><strong>{e(n)}</strong><small>{e(t)}</small></div>' for n,t in rows)+'</div>'
def diagram(r):
 out=[f'<svg class="diagram" viewBox="-25 -35 {r["width"]+50} {r["depth"]+90}" xmlns="http://www.w3.org/2000/svg" aria-label="Plan calculé du lieu, pas une capture"><rect x="0" y="0" width="{r["width"]}" height="{r["depth"]}" fill="#10252e" stroke="#608091"/>']
 for b in r['solids']:
  out.append(f'<rect x="{b["x"]}" y="{b["z"]}" width="{b["w"]}" height="{b["d"]}" fill="{"#649faa" if b.get("material")=="glass" else "#516876"}" fill-opacity=".65" stroke="#9db2b8"/><text x="{b["x"]+3}" y="{b["z"]+14}" font-size="11" fill="#e3e1c7">{e(b["id"])}</text>')
 for b in r['doors']+r['hatches']:out.append(f'<rect x="{b["x"]}" y="{b["z"]}" width="{b["w"]}" height="{b["d"]}" fill="#b2925655" stroke="#dabd7e"/>')
 for c in r['controls']:
  out.append(f'<circle cx="{c["x"]}" cy="{c["z"]}" r="8" fill="{"#b9dfde" if c["circuit"]=="service" else "#dab981"}"/><text x="{c["x"]+13}" y="{c["z"]+4}" font-size="12" fill="#e3e4ca">{e(c["id"])}</text>')
 for l in r['props']:
  if l['type']=='lamp':out.append(f'<rect x="{l["x"]-10}" y="{l["z"]-4}" width="20" height="8" fill="#d8d7a8"/>')
 for x in r['exits']:out.append(f'<circle cx="{x["x"]}" cy="{x["z"]}" r="14" fill="#172c39" stroke="#98d0c1"/><text x="{max(30,min(1170,x["x"]+15))}" y="{x["z"]-18}" fill="#a3cfc7" font-size="12">{e(x["label"])}</text>')
 return ''.join(out)+'</svg>'
old=(R/'CODEX_LEVEL_DESIGN_V111.md').read_text();rules=[]
for m in re.finditer(r'^### (\d+) — (.+)\n+([\s\S]*?)(?=\n##|\Z)',old,re.M):
 if int(m[1])<=36:rules.append((m[2],m[3].strip()))
assert len(rules)==36
rules[0]=('Étendre un trajet sans allonger la liste des objectifs','V112 conserve les huit lieux hérités et ajoute l’atelier optique puis la coursive des conduites. Dix inspections, neuf lieux de l’opération, onze liaisons réciproques et cinq objectifs locaux. Deux nouveaux contacts sont catalogués dans la dérivation. Aucun objectif obligatoire nouveau : la collecte des balises et ce trajet restent facultatifs.')
rules[10]=('Conserver la menace et les pertes','Treize ennemis et une sentinelle existent dans le catalogue. Douze contacts appartiennent au réseau des neuf lieux de l’opération ; le Sulaco reste isolé en inspection. Une créature qui traverse conserve son identité, sa vie et sa piste. Quitter une pièce ne retire pas un ennemi de la condition de défense. V112 ne fait apparaître aucun contact lors d’un lancer.')
rules[17]=('Un battant commun à deux pièces','Les onze liaisons ont chacune une structure unique : intégrité 100, renfort de 0 à 72, état de brèche et compte d’impacts. Les vingt-deux volumes de seuil sont dérivés de ces états partagés. Operations–Atelier et Coursive–Infirmerie commencent fermés ; Atelier–Coursive commence ouvert. La rupture agit sur les deux faces pour corps, vue, tirs, chemins et franchissements.')
rules[34]=('Une reprise doit conserver le noir','L’éclairage garde son contrat strict. L’enveloppe V112 inclut aussi les dix mondes et les balises. V111 passe d’abord par son propre validateur : tous ses anciens circuits, acteurs, munitions et ressources restent identiques. Les deux lieux nouveaux commencent hors tension, sans balise offerte. La reprise reste en pause et ne simule pas de temps pendant le chargement.')
rules += [
('Une dérivation avec une fonction et deux extrémités','Operations → Atelier optique → Coursive des conduites → Infirmerie forme une autre voie médicale. Les trois raccords sont réellement réciproques, avec seuil et arrivée propres. Ouvrir les deux extrémités fermées prend le temps normal et laisse passer les contacts ; la dérivation n’est pas un bouton de téléportation.'),
('L’atelier : calibrer, stocker, puis laisser circuler','La partition centrale protège deux moitiés distinctes ; l’armoire, les bancs et la baie de calibration servent de supports et de masses de contournement. Le stock n’est pas sur le point d’arrivée : il est placé après la première exposition. La commande de service peut rallumer la pièce mais ne distribue pas les balises.'),
('La coursive : conduites et visibilité interrompue','Les échangeurs, pieds de vanne et cabinets organisent un axe coupé par une porte intérieure. La sortie rejoint un seuil de l’infirmerie, hors du lit ouest. Un Facehugger est un contact existant de cette salle, pas une apparition au moment où le joueur allume une source. Tester les gabarits à l’arrivée des deux faces.'),
('Un seul coffret et exactement quatre charges','Le coffret beacon-case est posé sur beacon-case-body au sol de l’atelier. Il bloque corps et projectiles, sans boucher la vue par une hauteur fictive. E à portée 76 prépare 1,05 seconde. Créditer quatre charges uniquement à l’achèvement. Le couvercle montre ensuite le fond vide ; revenir, interrompre ou importer ne produit rien de plus.'),
('Engager une direction, pas poursuivre le curseur','P prépare un lancer de 0,6 seconde vers un point visé validé au départ. Le personnage baisse son arme et présente l’objet. Marcher, tirer ou perdre des PV interrompt sans débit. Bouger la visée ne déplace pas la destination engagée. La pause fige l’amorçage et la consommation n’a lieu qu’à son terme.'),
('Atterrir sur le même sol que les acteurs','Portée maximale 360, distance minimale 28, rayon du disque 4 unités. Le segment de lancer est tracé contre les mêmes volumes de corps/projectiles. Le verre peut laisser voir mais arrête le lancer. Une fermeture intervenant pendant le geste recalcule l’arrivée sans passer à travers le battant. Aucun rebond ni vol balistique continu n’est simulé.'),
('Une lumière qui respecte les cloisons','La balise émet localement dans un rayon maximal de 225 unités. Le rendu et la reconnaissance utilisent les volumes opaques et les limites de la pièce. L’intensité décroît avec la distance ; le bord n’est pas intégralement une zone de reconnaissance garantie. Le verre suit ses propriétés de vue, indépendantes des collisions des balles.'),
('Le porteur n’est pas le propriétaire de la lumière','Une source éclaire autant un Marine, Newt ou un Xéno selon leur position. La reconnaissance du joueur, de l’escouade, de la sentinelle et des ennemis reçoit la même contribution. Éclairer la zone de repli peut donc faciliter le ciblage hostile. Ne jamais en faire une invisibilité gratuite ou un arrêt de la cognition.'),
('Trente-six secondes dans une horloge commune','Chaque balise garde litAt et expiresAt espacés de 36 secondes. Les six dernières secondes réduisent son intensité. L’horloge est celle de l’opération : une pièce non visitée à l’écran vieillit aussi. Pause et import ne consomment pas le temps. Le disque inerte reste au sol après extinction et ne peut pas être récupéré ou rechargé.'),
('Un impact bref, pas une sirène ni une vague','L’atterrissage produit un stimulus d’équipement de portée 280, propagé par le système acoustique existant. Il peut influencer une piste, pas hypnotiser une créature. Il ne crée, tue ou déplace aucun acteur. Une source active n’émet pas une boucle de bruit ; pour une diversion prolongée, la commande de diagnostic garde son rôle propre.'),
('Ne pas cumuler des sources en projecteur infini','Les contributions lumineuses emploient un maximum, pas une addition arbitraire. Le stock de quatre bornes limite naturellement le travail du renderer et le registre. Aucune source ne traverse entre deux pièces, même si un sas est ouvert ; une transmission lumineuse inter-pièces nécessiterait une nouvelle règle partagée et une recette dédiée.'),
('Reprendre sans dupliquer les charges','Schéma 112 : charges + dépenses = quatre seulement après collecte ; nombre de disques = dépenses ; identifiants uniques et ordonnés ; durée exacte et dates dans le temps de l’opération. Rejeter propriétés inconnues, coordonnées dans un support fixe et bilan d’actions incohérent avant mutation. Un battant mobile refermé sur un disque l’occulte sans invalider une ancienne sauvegarde légale. Les huit anciens lieux V111 sont migrés sans cadeaux, les réserves de balises sont vides jusqu’à la collecte.')
]
assert len(rules)==48
md=['# CODEX LEVEL DESIGN — ALIENS V112 / Baliser le repli','Suite autonome V111. Deux lieux et trois raccords nouveaux. Cinq objectifs locaux conservés ; aucune fusion aux 64 salles natives.','## Règles de conception']
body='<p class="kicker">Tantalus / Aliens 1986 · Codex de level design V112</p><h1>Baliser le repli</h1><p class="lead">Le raccourci traverse deux pièces hors tension. Une lumière au sol ouvre une ligne de vue, mais ne choisit pas son camp.</p>'+metrics([(len(rules),'règles de conception'),(10,'fiches de lieux'),(3,'nouveaux raccords'),(4,'balises finies')])
body+='<nav><a href="JOUER_ALIENS_V112.html">Jouer V112</a><a href="RAPPORT_ILLUSTRE_V112.html">Rapport illustré</a><a href="#regles">Règles</a><a href="#lieux">Lieux et géométrie</a></nav><div class="callout">Code de la branche autonome réelle, pas une extension appliquée au moteur natif. Les schémas ci-dessous sont calculés depuis les données, ce ne sont pas des captures. Les captures du programme exécuté figurent dans le rapport.</div>'
body+='<h2 id="regles">Les contrats de level design</h2>'
for i,(title,text) in enumerate(rules,1):
 body+=f'<details><summary>{i:02} — {e(title)}</summary><p>{e(text)}</p></details>';md += [f'### {i:02} — {title}',text]
body+='<h2>Commandes et réserves</h2>'+table(['Geste','Temps','Portée / limite','Conséquence'],[['Coffret E','1,05 s','76 unités ; atelier','Quatre charges, une seule fois'],['Lancer P','0,6 s','28–360 unités ; segment obstruable','Une charge, aucune récupération'],['Balise au sol','36 s','225 unités maximum','Fading sur les 6 dernières secondes'],['Service K','0,95 s','Commande propre à la pièce','Circuit indépendant'],['Torche L','immédiat','Cône maximal 520','Source personnelle distincte']])
body+='<h2 id="lieux">Dix lieux, un seul contrat spatial</h2><p>Le réseau de l’opération compte neuf lieux ; le Sulaco reste une inspection séparée. Les nouveaux sas Operations–Atelier et Coursive–Infirmerie commencent fermés. Le lien Atelier–Coursive commence ouvert. Les huit anciens lieux gardent leur catalogue et leurs circuits initiaux.</p><label for="filter">Rechercher un lieu, équipement ou raccord</label><input id="filter" type="search" placeholder="Atelier, conduites, Operations, infirmerie…" autocomplete="off"><p id="filter-note" class="small">10 lieux affichés</p><div class="rooms">'
for r in C['rooms']:
 new=r['id'].startswith('v112-');lp=next(x for x in C['lightingProfiles'] if x['roomId']==r['id']);search=' '.join([r['title'],r['id'],r['goal'],r.get('family','')]+[x['label'] for x in r['exits']]+[p['id'] for p in r['props']]).lower()
 body+=f'<article class="room{" new" if new else ""}" data-search="{e(search)}"><p class="kicker">{"NOUVEAU / V112" if new else "HÉRITÉ / CONSERVÉ"} · {e(r["mode"])}</p><h2>{e(r["title"])}</h2><p>{e(r["goal"])}</p><p class="small">{e(r["id"])} · {r["width"]} × {r["depth"]} unités · {"opération et inspection" if r["connected"] else "inspection isolée"}</p>'
 body+='<figure>'+diagram(r)+'<figcaption>Plan calculé depuis les volumes physiques. Gris : solides ; ambre : portes et sas ; cyan : commandes ; points : seuils. Pas une capture du jeu.</figcaption></figure>'
 body+=table(['Raccord','Seuil local x,z','Arrivée locale x,z','Destination','Sas initial'],[[x['label'],f"{x['x']}, {x['z']}",f"{x['arrival']['x']}, {x['arrival']['z']}",x['to']['room'], 'fermé' if next(l for l in C['links'] if l['id']==x['linkId']).get('initialOpen',True)==False else 'ouvert']for x in r['exits']])
 body+=f'<p>Commande de service : <code>{e(lp["controlId"])}</code> ; {len(lp["lamps"])} lampes sur supports. État initial : <strong>{"coupé" if new else "allumé"}</strong>. Le service et les balises restent indépendants.</p>'
 body+=table(['Prop','Type','Support','Position x,z','Élévation'],[[p['id'],p['type'],p.get('supportId') or p.get('support','sol/mur défini au rendu'),f"{p['x']}, {p['z']}",p.get('elevation',0)]for p in r['props']])
 body+=table(['Volume','x,z','w,d','Hauteur','Matériau'],[[p['id'],f"{p['x']}, {p['z']}",f"{p['w']}, {p['d']}",p.get('h','—'),p.get('material','structure')]for p in r['solids']+r['doors']])
 body+='</article>';md += [f'## {r["title"]}',f'{r["id"]} — {r["mode"]}. {r["goal"]}',('Nouveau lieu V112, service coupé au départ.' if new else 'Lieu hérité, catalogue conservé.'),'```json\n'+json.dumps({'exits':r['exits'],'solids':r['solids'],'doors':r['doors'],'controls':r['controls'],'props':r['props']},ensure_ascii=False,indent=2)+'\n```']
body+='</div><h2>Recette minimale d’une salle balisée</h2><p>Tester les seuils aux deux faces, les arrivées et les gabarits. Avancer avec la torche puis l’éteindre ; vérifier un lancer sur sol, contre cloison et contre verre ; interrompre et reprendre à mi-geste ; confirmer la perception des deux côtés ; quitter la salle puis revenir après extinction. Les charges ne doivent jamais être recréditées par la visite ou l’import. Achever aussi l’itinéraire précédent sans emprunter la dérivation.</p><p class="small">Contrat V112 : '+e(C['contract'])+'. Rendu procédural stylisé. Tirs locaux et transferts discrets. Les sprites définitifs et l’intégration native ne sont pas certifiés par ces plans.</p>'
js='''<script>const f=document.querySelector('#filter');f.oninput=()=>{let n=0;for(const r of document.querySelectorAll('.room')){const show=r.dataset.search.includes(f.value.toLowerCase());r.classList.toggle('hide',!show);if(show)n++;}document.querySelector('#filter-note').textContent=n+' lieux affichés';};</script>'''
(R/'CODEX_LEVEL_DESIGN_V112.html').write_text(page('Aliens V112 — Codex Baliser le repli',body,js));(R/'CODEX_LEVEL_DESIGN_V112.md').write_text('\n\n'.join(md)+'\n')
selection=[('44_atelier_entree.png','Un nouvel accès de service'),('45_coffret_ouvert.png','Le coffret reste vide après collecte'),('46_balise_sans_torche.png','Une source indépendante de la torche'),('47_atelier_balisage.png','L’atelier éclairé par une balise'),('48_coursive_conduites.png','La coursive et ses occultations'),('49_carte_derivation.png','Le nouveau raccord au bloc médical'),('50_defense_sur_balise.png','Défendre sans alimentation ni torche'),('51_balises_paysage.png','Commandes en paysage court'),('52_balises_portrait.png','Commandes en portrait'),('53_repli_balises.png','Toute l’équipe au repli')]
by={c['file']:c for c in B['captures']}
def picture(file,title):
 c=by[file];raw=(R/'report/captures-v112'/file).read_bytes();assert raw.startswith(b'\x89PNG\r\n\x1a\n');return f'<figure><h3>{e(title)}</h3><img loading="lazy" src="data:image/png;base64,{base64.b64encode(raw).decode()}" alt="{e(title)} — capture directe du jeu V112"><figcaption>{e(c["origin"])}. <strong>{e(file)}</strong> : PNG brut de Chromium, non retouché. Aucun concept généré ni reconstruction graphique à partir de coordonnées.</figcaption></figure>'
body='<p class="kicker">ALIENS V112 / rapport de livraison</p><h1>Baliser le repli</h1><p class="lead">Quatre balises, deux pièces hors tension et un autre chemin vers Newt. Éclairer une zone ne fait pas disparaître ce qui vous poursuit.</p>'+metrics([(node,'tests Node réussis'),(len(B['tests']),'contrôles navigateur'),(7,'opérations terminées'),(len(B['captures']),'captures brutes')])
body+='<nav><a href="JOUER_ALIENS_V112.html">Jouer V112</a><a href="CODEX_LEVEL_DESIGN_V112.html">Codex</a><a href="#preuves">Vérifications</a><a href="#limites">Périmètre</a></nav><div class="callout">Suite de l’archive autonome V111 fournie, pas une fusion au moteur Tantalus natif. Les dix images de ce rapport sont intégrées sans modification depuis les PNG Chromium. Les légendes distinguent les gestes de l’interface et les reprises d’exports valides des parcours.</div>'
body+='<h2>Une boucle facultative, pas une nouvelle liste d’objectifs</h2><p>Operations rejoint maintenant l’atelier optique, puis la coursive des conduites et l’infirmerie. Ces deux nouveaux lieux ont leurs volumes propres et deux contacts catalogués. Les trois raccords sont réciproques. Les deux extrémités fermées isolent ce détour tant qu’on ne l’ouvre pas ; une fois ouvertes, l’escouade et les menaces les empruntent selon les mêmes règles que le réseau existant.</p>'
body+='<h2>Lumière limitée et arbitrage partagé</h2>'+table(['Geste','Durée','Conséquence'],[['Coffret de l’atelier — E','1,05 s','4 charges, une seule collecte'],['Amorcer et lancer — P','0,6 s','Point visé engagé ; rayon 4, distance 28 à 360'],['Source au sol','36 s','Rayon maximal 225 ; fade final de 6 s'],['Impact sonore','bref','Stimulus équipement, rayon 280 ; aucun spawn']])
body+='<p>Le lancer utilise le segment physique corps/projectiles, la lumière utilise les volumes opaques. Le verre peut transmettre la lumière sans laisser passer l’objet. Marcher, tirer, perdre de la vie ou perdre une arrivée valide annule le geste sans consommation. La pause suspend le temps. La source est locale, fixe et éclaire aussi les membres de l’équipe aux yeux des Xénos. Elle ne recharge, soigne ou valide rien.</p>'
for f,t in selection:body+=picture(f,t)
body+='<h2 id="preuves">Ce qui a réellement été exécuté</h2>'+table(['Recette','Résultat','Portée'],[['Node',node,'408 tests hérités réexécutés +78 nouveaux tests dirigés'],['Navigateur',len(B['tests']),'187 contrôles hérités réexécutés +49 nouveaux contrôles balises'],['Parcours complets',7,'2 directs/service, 2 logistiques, brèche, noir, dérivation balisée'],['Captures',len(B['captures']),'10 PNG embarqués byte-for-byte']])
body+='<h3>Du départ normal au repli avec les balises</h3><p>Le pilote lit le monde pour choisir ses chemins, mais n’écrit ni positions, ni vies, ni chargeurs, ni circuits ou objectifs. Il utilise les entrées publiques de mouvement, E, R, tir, ordres, torche et P. Les deux imports proviennent de ses propres exports pendant la collecte et l’amorçage. Les tests dirigés qui préparent un état précis sont distincts de cette conduite complète.</p>'
body+=table(['Entrées / sous-pas','Temps simulé','Franchissements ennemis','Charges dépensées / restantes','État final'],[[D['inputs'],f"{D['elapsed']:.3f} s",D['enemyTransfers'],f"{D['beacons']['spent']} / {D['beacons']['charges']}",'repli confirmé']])
body+=table(['Membre','PV finaux','Munitions'],[[a['id'],a['hp'],a['ammo']] for a in D['team']])
sentry=lambda d:next(a for a in d['worlds']['v106-sentry']['actors'] if a['id']=='sentry-a')['ammo']
a=J('report/beacon-states-v112/11-sentinelle-balise.json');z=J('report/beacon-states-v112/12-defense-balisee.json')
body+=f'<p>La défense est terminée circuit de service et torche personnels coupés : la sentinelle passe de <strong>{sentry(a)} à {sentry(z)} cartouches</strong>. Le groupe revient avec une balise inutilisée, non remboursée. Les premières sources expirent pendant les déplacements entre pièces ; les disques restent dans le registre. Les {D["elapsed"]:.3f} secondes simulées ne représentent pas une durée de jeu humaine.</p>'
body+='<h2 id="limites">Ce qui n’est pas revendiqué</h2><p>La branche autonome compte dix inspections et neuf lieux reliés, pas une adaptation native de 64 salles. Aucun push GitHub, déploiement Vercel ou raccord actif de l’ancien adaptateur n’est effectué. Le final historique Reine/P-5000/sas n’est pas remplacé. La population supplémentaire est composée de deux contacts de catalogue, pas d’une génération à la demande.</p><p>Rendu procédural stylisé, éclairage 2D occulté et service global par pièce. Le lancer est une préparation suivie d’une arrivée calculée, pas une simulation de vol/rebond. Pas de lumière ni de tirs entre les pièces, pas de terrain extérieur continu, de récupération des balises, d’illumination volumétrique ou de sprites finaux. Les instruments sur 844 × 390 restent petits ; les viewports testés sont émulés et ne certifient pas un téléphone physique.</p><p>Le document exact est chargé dans Chromium avec son chargeur Blob normal. Les contrôles de distribution, de transport file:// et d’intégrité sont séparés des assertions gameplay. Une vérification ne démontre pas une absence universelle de bugs.</p>'
body+='<h2>Provenance</h2><p class="small">Archive source V111 : 5c90e5281869f735f9ffb8a19cdc57a45473938d56b6920813f4ac76a9a23cee<br>HTML V112 : '+B['htmlSha256']+'<br>Contrat : '+C['contract']+'</p>'
(R/'RAPPORT_ILLUSTRE_V112.html').write_text(page('Aliens V112 — Rapport illustré Baliser le repli',body))
